public class WarehouseInfo
{
    public string WarehouseId { get; set; } = "WH-A";
    public string WarehouseName { get; set; } = "Warehouse A";

    public static readonly (string Id, string Name)[] AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];
}

namespace sv_272326354039436dbd8bd26c9c8aaae8.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int LatestLowStockCount { get; private set; }

    /// <summary>
    /// Fired whenever new alert data is available.
    /// Subscribers MUST wrap StateHasChanged in InvokeAsync because
    /// this fires from a background thread (timer).
    /// </summary>
    public event Action? OnChange;

    /// <summary>Simulates a database query — returns a random number 0–15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begin polling every 10 seconds for the given warehouse.
    /// Reference-counted: multiple callers share one timer.
    /// </summary>
    public void StartPolling(string warehouseId)
    {
        _subscriberCount++;
        if (_timer is not null) return; // already running

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    /// <summary>Stop polling when no subscribers remain.</summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount > 0) return;

        _cts?.Cancel();
        _timer?.Dispose();
        _timer = null;
        _cts?.Dispose();
        _cts = null;
    }

    /// <summary>
    /// Restart the poll loop targeting a different warehouse.
    /// Called when the user switches warehouses while polling is active.
    /// </summary>
    public void RestartPolling(string warehouseId)
    {
        if (_timer is null) return;

        _cts?.Cancel();
        _timer.Dispose();
        _cts?.Dispose();

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(warehouseId, _cts.Token);
    }

    private async Task PollLoopAsync(string warehouseId, CancellationToken ct)
    {
        // Fire immediately on start so UI shows data right away
        LatestLowStockCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                LatestLowStockCount = await GetLowStockCountAsync(warehouseId);
                OnChange?.Invoke();
            }
        }
        catch (OperationCanceledException) { /* expected on stop/restart */ }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

