arguments.new_str:
using Microsoft.AspNetCore.Components;
using sv_272326354039436dbd8bd26c9c8aaae8.Components;
using sv_272326354039436dbd8bd26c9c8aaae8.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Warehouse selection — CascadingValueSource crosses render-mode boundaries,
// and scoped lifetime gives each circuit (user) its own independent selection.
builder.Services.AddScoped(sp =>
{
    var info = new WarehouseInfo();
    return new CascadingValueSource<WarehouseInfo>(info, isFixed: false);
});
builder.Services.AddCascadingValue(sp =>
    sp.GetRequiredService<CascadingValueSource<WarehouseInfo>>());

// Inventory alert service — scoped so each user has independent polling/counts.
builder.Services.AddScoped<InventoryAlertService>();

