@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_272326354039436dbd8bd26c9c8aaae8.Services

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard — @_warehouseName</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.LatestLowStockCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.LatestLowStockCount
                </p>
                <p class="text-muted">items below minimum level</p>
            </div>
        </div>
    </div>
    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Details</h5>
                <p>Monitoring <strong>@_warehouseName</strong> (ID: @_warehouseId)</p>
                <p>Alert data refreshes every 10 seconds while this page is open.</p>
                <p>Last refreshed: @_lastRefresh.ToString("T")</p>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private string _warehouseId = "WH-A";
    private string _warehouseName = "Warehouse A";
    private DateTime _lastRefresh = DateTime.Now;
    private Action? _handler;

    protected override void OnInitialized()
    {
        ApplyWarehouse();

        _handler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;

        // Start polling for the current warehouse
        AlertService.StartPolling(_warehouseId);
    }

    protected override void OnParametersSet()
    {
        var previousId = _warehouseId;
        ApplyWarehouse();

        if (previousId != _warehouseId)
        {
            // Warehouse changed — restart polling for the new warehouse
            AlertService.RestartPolling(_warehouseId);
        }
    }

    private void ApplyWarehouse()
    {
        if (Warehouse is not null)
        {
            _warehouseId = Warehouse.WarehouseId;
            _warehouseName = Warehouse.WarehouseName;
        }
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        AlertService.StopPolling();
    }
}

